// Escape — ferme tooltip popover ou modale la plus haute
document.addEventListener('keydown', function (e) {
    if (e.key !== 'Escape' || e.defaultPrevented || e.isComposing) return;
    const customTooltip = document.getElementById('customTooltip');
    if (customTooltip && customTooltip.style.display !== 'none' && customTooltip.offsetParent !== null) {
        customTooltip.style.display = 'none';
        if (window.game && typeof window.game.hideTooltip === 'function') window.game.hideTooltip();
        e.preventDefault();
        return;
    }
    if (!closeTopmostModalUI()) return;
    e.preventDefault();
});

// Clic extérieur pour fermer le tooltip popover
document.addEventListener('pointerdown', (e) => {
    const customTooltip = document.getElementById('customTooltip');
    if (customTooltip && customTooltip.style.display !== 'none') {
        const target = e.target as HTMLElement | null;
        if (target && !customTooltip.contains(target) && !target.closest('#synergyBtn')) {
            customTooltip.style.display = 'none';
            if (window.game && typeof window.game.hideTooltip === 'function') window.game.hideTooltip();
        }
    }
});

// Navigation clavier dans les onglets (ARIA)
document.addEventListener('keydown', (e: KeyboardEvent) => {
    const currentTab = eventTargetElement(e.target)?.closest('[role="tab"]') as HTMLElement | null;
    if (!currentTab) return;

    const tabList = currentTab.closest('[role="tablist"]');
    if (!tabList) return;

    const tabs = Array.from(tabList.querySelectorAll<HTMLElement>('[role="tab"]'))
        .filter((tab) => {
            const disabled = tab instanceof HTMLButtonElement ? tab.disabled : false;
            return !disabled && !tab.hidden && window.getComputedStyle(tab).display !== 'none';
        });
    if (tabs.length < 2) return;

    const currentIndex = tabs.indexOf(currentTab);
    if (currentIndex === -1) return;

    let nextIndex = -1;
    if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
        nextIndex = (currentIndex + 1) % tabs.length;
    } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
        nextIndex = (currentIndex - 1 + tabs.length) % tabs.length;
    } else if (e.key === 'Home') {
        nextIndex = 0;
    } else if (e.key === 'End') {
        nextIndex = tabs.length - 1;
    } else {
        return;
    }

    e.preventDefault();
    const nextTab = tabs[nextIndex];
    if (!nextTab) return;
    nextTab.focus();
    nextTab.click();
});

// Navigation clavier entre les zones (Gauche/Droite) et les régions (Haut/Bas)
document.addEventListener('keydown', (e: KeyboardEvent) => {
    handleZoneAndRegionKeyboardNavigation(e);
});

// ============================================================
// AUTO-INITIALISATION
// ============================================================

function initCustomTooltipHoverListeners(): void {
    const tipEl = document.getElementById('customTooltip');
    if (!tipEl || tipEl.dataset.hasHoverListeners === 'true') return;
    tipEl.dataset.hasHoverListeners = 'true';
    tipEl.addEventListener('mouseenter', () => {
        const gm = (window as unknown as { game?: { hideTooltipTimer?: unknown } }).game;
        if (gm && gm.hideTooltipTimer) {
            clearTimeout(Number(gm.hideTooltipTimer));
            gm.hideTooltipTimer = null;
        }
    });
    tipEl.addEventListener('mouseleave', () => {
        const gm = (window as unknown as { game?: { hideTooltip?: () => void } }).game;
        if (gm && typeof gm.hideTooltip === 'function') {
            gm.hideTooltip();
        }
    });
}

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        initializeTabAccessibility();
        initMobileLayout();
        initMobileTouchListeners();
        initSubTabEdgeAutoScroll();
        initTabsEdgeAutoScroll();
        initCustomTooltipHoverListeners();
    });
} else {
    initializeTabAccessibility();
    initMobileLayout();
    initMobileTouchListeners();
    initSubTabEdgeAutoScroll();
    initTabsEdgeAutoScroll();
    initCustomTooltipHoverListeners();
}

let lastMobileViewport = isMobileViewport();
let lastLayoutKey = typeof window !== 'undefined'
    ? `${window.innerWidth}x${window.innerHeight}`
    : '0x0';

function refreshZoneMapOnLayoutChange(): void {
    if (game && typeof game.updateZoneSelector === 'function') {
        game.updateZoneSelector();
    }
}

function handleViewportLayoutChange(): void {
    const isMobile = isMobileViewport();
    const layoutKey = `${window.innerWidth}x${window.innerHeight}`;

    if (!isMobile) {
        dismissMobileSwipeHint();
        syncMobilePanelState(null);
        const combatArea = document.querySelector('.combat-area');
        const teamArea = document.querySelector('.team-area');
        const secondaryContent = document.getElementById('secondaryContent');
        [combatArea, teamArea, secondaryContent].forEach(el => {
            if (el) el.classList.remove('mobile-active');
        });
    } else {
        const anyActive = document.querySelector('.combat-area.mobile-active, .team-area.mobile-active, .secondary-content.mobile-active');
        if (!anyActive) switchMobilePanel('combat');
        syncMobilePanelStateFromDom();
    }

    if (isMobile !== lastMobileViewport) {
        lastMobileViewport = isMobile;
        lastLayoutKey = layoutKey;
        refreshZoneMapOnLayoutChange();
    } else if (layoutKey !== lastLayoutKey) {
        lastLayoutKey = layoutKey;
        refreshZoneMapOnLayoutChange();
    }

    initSubTabEdgeAutoScroll();
    initTabsEdgeAutoScroll();
}

// Re-init when resizing between mobile/desktop or rotating within mobile
window.addEventListener('resize', handleViewportLayoutChange);
window.addEventListener('orientationchange', handleViewportLayoutChange);

window.addEventListener('blur', () => {
    document.querySelectorAll('.sub-tabs-container').forEach((el) => stopSubTabEdgeAutoScroll(el as HTMLElement));
    document.querySelectorAll('.tabs-container').forEach((el) => stopTabsEdgeAutoScroll(el as HTMLElement));
});

document.addEventListener('visibilitychange', () => {
    if (document.visibilityState !== 'visible') {
        document.querySelectorAll('.sub-tabs-container').forEach((el) => stopSubTabEdgeAutoScroll(el as HTMLElement));
        document.querySelectorAll('.tabs-container').forEach((el) => stopTabsEdgeAutoScroll(el as HTMLElement));
    }
});

